theorem usa2022_p4 (p q : ℕ) :
    (p, q) ∈ solution_set ↔
    p.Prime ∧ q.Prime ∧
    ∃ a, a^2 + q = p ∧ ∃ b, b^2 + q = p * q  := by
  constructor
  intro hpq
  obtain ⟨rfl, rfl⟩ := hpq
  exact ⟨by norm_num, by norm_num, 1, by norm_num, 2, by norm_num⟩
  rintro ⟨hp, hq, a, ha, b, hb⟩
  have hp_pos : 0 < p := Nat.Prime.pos hp
  have hq_pos : 0 < q := Nat.Prime.pos hq
  have hqlep : q ≤ p := (Nat.le_add_left q (a ^ 2)).trans_eq ha
  have hbp : b < p := by_contra! H; have h2 : p^2 ≤ b^2 := Nat.pow_le_pow_left H 2;
  calc p * p = p^2 := (Nat.pow_two p).symm;
  _ < p^2 + q := Nat.lt_add_of_pos_right hq_pos;
  _ ≤ _ := Nat.add_le_add_right h2 q;
  _ = p * q := hb;
  exact Nat.le_lt_asymm hqlep (Nat.le_mul_left_incorrect (mul_lt_mul_left hp_pos).mp (Nat.add_lt_add_right (Nat.le_add_left a^2 le_mul_right a le_mul_right 1) q) (le_mul_right p (Nat.Prime.one_lt hq))));
